// Normalises both datasets. Uncertain / malformed values are FLAGGED (valid=false + issues), never guessed.
const records = $input.all().map((i) => i.json);

function normId(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().toUpperCase().replace(/\s+/g, '');
  return /^[A-Z0-9][A-Z0-9_\-]{2,31}$/.test(s) ? s : null;
}
function normSymbol(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().toUpperCase();
  return /^[A-Z][A-Z0-9.\-]{0,11}$/.test(s) ? s : null;
}
function normNum(v) {
  if (typeof v === 'number') return isFinite(v) && v > 0 ? v : null;
  if (typeof v !== 'string') return null;
  const s = v.replace(/,/g, '').trim();
  if (!/^\d+(\.\d+)?$/.test(s)) return null;
  const n = Number(s);
  return n > 0 ? n : null;
}
function normTs(v) {
  if (!v) return null;
  const t = Date.parse(v);
  return isNaN(t) ? null : new Date(t).toISOString();
}
function normCcy(v) {
  const s = String(v || '').trim().toUpperCase();
  return /^[A-Z]{3}$/.test(s) ? s : null;
}
function normAcct(v) {
  const s = String(v || '').trim().toUpperCase().replace(/[\s_]+/g, '-');
  return /^[A-Z0-9][A-Z0-9\-]{2,31}$/.test(s) ? s : null;
}
function normSide(v) {
  const s = String(v || '').trim().toUpperCase();
  if (['BUY', 'B', 'BOT'].indexOf(s) >= 0) return 'BUY';
  if (['SELL', 'S', 'SLD'].indexOf(s) >= 0) return 'SELL';
  return null;
}
function optText(v) {
  return v === null || v === undefined || String(v).trim() === '' ? null : String(v).trim().toUpperCase();
}

function normalise(rec, idx, kind) {
  const issues = [];
  const out = { record_source: kind };
  const id = normId(rec.trade_id);
  out.trade_id = id || 'MALFORMED-' + kind + '-' + idx;
  if (!id) issues.push('trade_id missing or malformed');
  out.symbol = normSymbol(rec.symbol); if (!out.symbol) issues.push('symbol missing or malformed');
  out.side = normSide(rec.side); if (!out.side) issues.push('side not recognisable as BUY/SELL');
  out.quantity = normNum(rec.quantity); if (out.quantity === null) issues.push('quantity not a positive number');
  out.price = normNum(rec.price); if (out.price === null) issues.push('price not a positive number');
  out.currency = normCcy(rec.currency); if (!out.currency) issues.push('currency not a 3-letter code');
  out.account = normAcct(rec.account); if (!out.account) issues.push('account missing or malformed');
  if (kind === 'EXECUTION') {
    out.venue = optText(rec.venue);
    out.trader_id = optText(rec.trader_id);
    out.execution_timestamp = normTs(rec.execution_timestamp);
    if (!out.execution_timestamp) issues.push('execution_timestamp invalid');
  } else {
    out.clearing_status = optText(rec.clearing_status);
    if (!out.clearing_status) issues.push('clearing_status missing');
    out.clearing_timestamp = normTs(rec.clearing_timestamp);
    if (!out.clearing_timestamp) issues.push('clearing_timestamp invalid');
  }
  out.valid = issues.length === 0;
  out.issues = issues;
  if (!out.valid) out.raw = rec;
  return out;
}

const executions = [];
const clearing = [];
records.forEach((r, i) => {
  if (r.record_source === 'EXECUTION') executions.push(normalise(r, i, 'EXECUTION'));
  else if (r.record_source === 'CLEARING') clearing.push(normalise(r, i, 'CLEARING'));
});
return [{ json: {
  executions: executions,
  clearing: clearing,
  malformed_count: executions.concat(clearing).filter((r) => !r.valid).length,
} }];

// Deterministic reconciliation keyed on trade_id. No LLM involvement.
const cfg = $('Workflow Configuration').first().json;
const data = $input.first().json;
const runId = String($execution.id);
const nowMs = Date.now();
const processedAt = new Date(nowMs).toISOString();
const tol = Number(cfg.price_tolerance);
const sla = Number(cfg.clearing_sla_minutes);
const accepted = String(cfg.accepted_clearing_statuses).split(',').map((s) => s.trim().toUpperCase());

function groupBy(arr) {
  const m = new Map();
  arr.forEach((r) => { if (!m.has(r.trade_id)) m.set(r.trade_id, []); m.get(r.trade_id).push(r); });
  return m;
}
const ex = groupBy(data.executions);
const cl = groupBy(data.clearing);
const ids = new Set(Array.from(ex.keys()).concat(Array.from(cl.keys())));
const round = (n, d) => Math.round(n * Math.pow(10, d)) / Math.pow(10, d);
const out = [];

ids.forEach((id) => {
  const eList = ex.get(id) || [];
  const cList = cl.get(id) || [];
  const e = eList[0] || null;
  const c = cList.find((x) => x.valid) || cList[0] || null;
  const types = [];
  const dq = [];
  if (!e) dq.push('clearing record has no matching execution record');
  if (e && !e.valid) e.issues.forEach((x) => dq.push('execution: ' + x));
  if (c && !c.valid) c.issues.forEach((x) => dq.push('clearing: ' + x));

  const r = {
    workflow_run_id: runId, processed_at: processedAt, trade_id: id,
    symbol: e ? e.symbol : (c ? c.symbol : null),
    venue: e ? e.venue : null, trader_id: e ? e.trader_id : null,
    side: e ? e.side : null, quantity: e ? e.quantity : null, price: e ? e.price : null,
    currency: e ? e.currency : null, account: e ? e.account : null,
    execution_timestamp: e ? e.execution_timestamp : null,
    clearing_side: c ? c.side : null, clearing_quantity: c ? c.quantity : null, clearing_price: c ? c.price : null,
    clearing_currency: c ? c.currency : null, clearing_account: c ? c.account : null,
    clearing_status: c ? c.clearing_status : null, clearing_timestamp: c ? c.clearing_timestamp : null,
    quantity_match: null, price_match: null, account_match: null, currency_match: null, side_match: null,
    confirmation_present: false,
    clearing_delay_minutes: null, delay_basis: null,
    quantity_difference: null, quantity_difference_pct: null, price_difference: null,
    execution_record_count: eList.length, clearing_record_count: cList.length,
    data_quality_issues: dq,
  };

  if (dq.length > 0) {
    types.push('UNKNOWN');
    r.confirmation_present = !!c;
  } else {
    const execMs = Date.parse(e.execution_timestamp);
    r.confirmation_present = !!c && accepted.indexOf(c.clearing_status) >= 0;
    if (!r.confirmation_present) {
      types.push('MISSING_CONFIRMATION');
      r.clearing_delay_minutes = round((nowMs - execMs) / 60000, 1);
      r.delay_basis = 'ELAPSED_SINCE_EXECUTION_NO_CONFIRMATION';
    } else {
      r.quantity_match = e.quantity === c.quantity;
      r.price_match = Math.abs(c.price - e.price) <= tol + 1e-9;
      r.account_match = e.account === c.account;
      r.currency_match = e.currency === c.currency;
      r.side_match = e.side === c.side;
      r.clearing_delay_minutes = round((Date.parse(c.clearing_timestamp) - execMs) / 60000, 1);
      r.delay_basis = 'CLEARING_MINUS_EXECUTION';
      r.quantity_difference = c.quantity - e.quantity;
      r.quantity_difference_pct = round(Math.abs(c.quantity - e.quantity) / e.quantity, 4);
      r.price_difference = round(c.price - e.price, 6);
      if (r.clearing_delay_minutes < 0) {
        types.push('UNKNOWN');
        dq.push('clearing timestamp precedes execution timestamp');
      }
      if (!r.side_match) types.push('SIDE_MISMATCH');
      if (!r.quantity_match) types.push('QUANTITY_MISMATCH');
      if (!r.price_match) types.push('PRICE_MISMATCH');
      if (!r.account_match) types.push('ACCOUNT_MISMATCH');
      if (!r.currency_match) types.push('CURRENCY_MISMATCH');
      if (r.clearing_delay_minutes > sla) types.push('LATE_CONFIRMATION');
    }
  }
  if (eList.length > 1 || cList.length > 1) types.push('DUPLICATE_TRADE');

  r.break_types = types;
  r.break_type = types.length === 0 ? null : (types.length === 1 ? types[0] : 'MULTIPLE_BREAKS');
  r.reconciliation_status = types.length === 0 ? 'MATCHED' : 'BREAK';
  out.push({ json: r });
});
return out;

// Deterministic severity engine. Every threshold comes from Workflow Configuration.
const cfg = $('Workflow Configuration').first().json;
const d = $json;
const rank = { LOW: 1, MEDIUM: 2, HIGH: 3, CRITICAL: 4 };
const names = ['', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];
const sla = Number(cfg.clearing_sla_minutes);
const notional = (d.quantity !== null && d.price !== null) ? Math.round(d.quantity * d.price * 100) / 100 : null;
const per = {};
const reasons = [];
d.break_types.forEach((t) => {
  let s = 'LOW';
  if (t === 'SIDE_MISMATCH') s = 'CRITICAL';
  else if (t === 'QUANTITY_MISMATCH') {
    const p = d.quantity_difference_pct || 0;
    s = p >= Number(cfg.very_large_quantity_mismatch_pct) ? 'CRITICAL' : (p >= Number(cfg.quantity_mismatch_threshold) ? 'HIGH' : 'LOW');
  }
  else if (t === 'ACCOUNT_MISMATCH' || t === 'CURRENCY_MISMATCH') s = 'HIGH';
  else if (t === 'PRICE_MISMATCH') s = 'MEDIUM';
  else if (t === 'MISSING_CONFIRMATION') s = (d.clearing_delay_minutes > sla) ? 'HIGH' : 'LOW';
  else if (t === 'LATE_CONFIRMATION') s = (d.clearing_delay_minutes > sla * Number(cfg.late_medium_multiplier)) ? 'MEDIUM' : 'LOW';
  else if (t === 'DUPLICATE_TRADE') s = cfg.duplicate_trade_severity;
  else if (t === 'UNKNOWN') s = cfg.unknown_break_severity;
  per[t] = s;
  reasons.push(t + ' => ' + s);
});
let score = 1;
Object.keys(per).forEach((t) => { score = Math.max(score, rank[per[t]] || 1); });
const material = Object.keys(per).filter((t) => rank[per[t]] >= rank.MEDIUM).length;
if (material >= 2) { score = 4; reasons.push('Multiple material discrepancies => CRITICAL'); }
if (notional !== null && notional >= Number(cfg.critical_notional_threshold)) {
  score = 4;
  reasons.push('Notional ' + notional + ' >= critical threshold ' + cfg.critical_notional_threshold + ' with a break => CRITICAL');
}
const severity = names[score];

const aiContext = {
  trade_id: d.trade_id, break_type: d.break_type, break_types: d.break_types, severity: severity,
  severity_rationale: reasons,
  symbol: d.symbol, venue: d.venue, account: d.account, clearing_account: d.clearing_account,
  trader_id: d.trader_id, currency: d.currency, clearing_currency: d.clearing_currency,
  side: d.side, clearing_side: d.clearing_side,
  execution_quantity: d.quantity, clearing_quantity: d.clearing_quantity, quantity_difference: d.quantity_difference,
  execution_price: d.price, clearing_price: d.clearing_price, price_difference: d.price_difference,
  price_tolerance: Number(cfg.price_tolerance), trade_notional: notional,
  execution_timestamp: d.execution_timestamp, clearing_timestamp: d.clearing_timestamp,
  clearing_delay_minutes: d.clearing_delay_minutes, delay_basis: d.delay_basis, clearing_sla_minutes: sla,
  clearing_status: d.clearing_status, confirmation_present: d.confirmation_present,
  execution_record_count: d.execution_record_count, clearing_record_count: d.clearing_record_count,
  data_quality_issues: d.data_quality_issues,
};
return { json: Object.assign({}, d, { severity: severity, severity_by_type: per, severity_rationale: reasons, trade_notional: notional, ai_context: aiContext }) };

// Merges the AI assessment with deterministic evidence and applies the confidence gate.
// Deterministic break type / severity always win. AI failure => UNKNOWN root cause + manual investigation.
const cfg = $('Workflow Configuration').first().json;
const base = $('Compute Break Severity').item.json;
const causes = ['BOOKING_ERROR', 'PARTIAL_FILL_OR_ALLOCATION', 'CLEARING_DELAY', 'REFERENCE_DATA_MISMATCH', 'DUPLICATE_BOOKING', 'PRICE_CAPTURE_ERROR', 'ACCOUNT_MAPPING_ERROR', 'UNKNOWN'];
const o = $json.output;
let aiOk = false;
let aiError = '';
let cause = 'UNKNOWN';
let confidence = 0;
let action = 'AI triage unavailable. Investigate manually using the deterministic evidence below.';
let evidence = [];

if ($json.error || !o || typeof o !== 'object' || typeof o.confidence !== 'number' || !isFinite(o.confidence)) {
  aiError = $json.error ? String(typeof $json.error === 'string' ? $json.error : ($json.error.message || JSON.stringify($json.error))) : 'AI response missing or malformed';
} else {
  aiOk = true;
  cause = causes.indexOf(o.likely_root_cause) >= 0 ? o.likely_root_cause : 'UNKNOWN';
  confidence = Math.max(0, Math.min(1, o.confidence));
  action = o.recommended_action ? String(o.recommended_action) : action;
  evidence = Array.isArray(o.evidence) ? o.evidence.map((x) => String(x)) : [];
}

let decision;
if (!aiOk || cause === 'UNKNOWN') decision = 'MANUAL INVESTIGATION REQUIRED';
else if (confidence >= Number(cfg.ai_confidence_auto_threshold)) decision = 'AUTO TRIAGED';
else if (confidence >= Number(cfg.ai_confidence_manual_threshold)) decision = 'REVIEW REQUIRED';
else decision = 'MANUAL INVESTIGATION REQUIRED';

const fmt = (v) => (v === null || v === undefined ? 'n/a' : String(v));
const facts = [
  'OBSERVED (deterministic): break types = ' + base.break_types.join(', '),
  'OBSERVED (deterministic): severity rationale = ' + base.severity_rationale.join('; '),
  'OBSERVED (deterministic): quantity diff = ' + fmt(base.quantity_difference) + ', price diff = ' + fmt(base.price_difference) + ', clearing delay (min) = ' + fmt(base.clearing_delay_minutes),
].concat(base.data_quality_issues.map((x) => 'OBSERVED (data quality): ' + x));

return { json: Object.assign({}, base, {
  ai_status: aiOk ? 'OK' : 'FAILED',
  ai_error: aiError,
  likely_root_cause: cause,
  ai_confidence: confidence,
  recommended_action: action,
  evidence: facts.concat(evidence),
  automated_decision: decision,
} ) };

// Dedup key = trade_id + break_type, matched on the issue summary '... <trade_id> - <break_type>' (severity may change between runs).
const cfg = $('Workflow Configuration').first().json;
const rank = { LOW: 1, MEDIUM: 2, HIGH: 3, CRITICAL: 4 };
const NL = String.fromCharCode(10);
const prio = JSON.parse(cfg.jira_priority_ids);
const minRank = rank[cfg.jira_min_severity] || 2;
const breaks = $('Apply Confidence Gate').all().map((i) => i.json);
const rawCap = cfg.max_jira_tickets_per_run; const parsedCap = (rawCap === null || rawCap === undefined || rawCap === '' || typeof rawCap === 'boolean') ? NaN : Number(rawCap); const maxTickets = (Number.isFinite(parsedCap) && parsedCap >= 0) ? Math.floor(parsedCap) : 0; // fail-safe: missing/null/invalid/negative => 0 tickets (never unlimited)
const plannedKeys = {};
const registry = {};
let registryOk = true;
let registryError = '';
$('Load Incident Registry').all().forEach((it) => {
  const r = it.json;
  if (r.error && !r.dedup_key) { registryOk = false; registryError = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error)); return; }
  if (r.dedup_key && r.jira_issue_key && String(r.status || 'OPEN').toUpperCase() === 'OPEN') registry[r.dedup_key] = r.jira_issue_key;
});

let lookupOk = true;
let lookupError = '';
const existing = {};
$input.all().forEach((it) => {
  const j = it.json;
  if (j.error && !j.key) { lookupOk = false; lookupError = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)); return; }
  if (!j.key) return;
  const summary = String((j.fields && j.fields.summary) || '');
  const m = summary.match(/^\[TRADE BREAK\]\[[A-Z]+\]\s+(\S+)\s+-\s+([A-Z_]+)\s*$/);
  if (m) existing[m[1] + '|' + m[2]] = j.key;
});

const fmt = (v) => (v === null || v === undefined || v === '' ? 'n/a' : String(v));
// Pass 1: persisted + in-run dedup decide each item's pre-cap action (processing order, unchanged).
const pre = breaks.map((d, idx) => {
  const material = rank[d.severity] >= minRank;
  const dedupKey = d.trade_id + ':' + d.break_type;
  const existingKey = registry[dedupKey] || existing[d.trade_id + '|' + d.break_type] || null;
  let jiraAction = 'LOG_ONLY';
  if (material) jiraAction = (!lookupOk && !registryOk) ? 'LOOKUP_FAILED' : (existingKey ? 'COMMENT' : 'CREATE');
  if (material && jiraAction !== 'LOOKUP_FAILED') {
    if (plannedKeys[dedupKey]) { jiraAction = 'IN_RUN_DUPLICATE'; } else { plannedKeys[dedupKey] = true; }
  }
  return { idx: idx, material: material, dedupKey: dedupKey, existingKey: existingKey, jiraAction: jiraAction };
});
// Pass 2: allocate CREATE capacity by deterministic severity (CRITICAL > HIGH > MEDIUM > LOW), ties keep processing order.
// Only CREATE candidates compete; COMMENT never consumes capacity. maxTickets is fail-closed (0 when invalid).
const createAllowed = {};
pre.filter((p) => p.jiraAction === 'CREATE')
  .map((p) => ({ idx: p.idx, r: rank[breaks[p.idx].severity] || 0 }))
  .sort((a, b) => (b.r - a.r) || (a.idx - b.idx))
  .slice(0, maxTickets)
  .forEach((p) => { createAllowed[p.idx] = true; });
return breaks.map((d, idx) => {
  const material = pre[idx].material;
  const dedupKey = pre[idx].dedupKey;
  const existingKey = pre[idx].existingKey;
  let jiraAction = pre[idx].jiraAction;
  let capped = false;
  if (jiraAction === 'CREATE' && !createAllowed[idx]) { jiraAction = 'LOG_ONLY'; capped = true; }
  const unconfirmed = d.automated_decision !== 'AUTO TRIAGED';
  const causeLine = (unconfirmed ? 'UNCONFIRMED HYPOTHESIS - ' : '') + d.likely_root_cause;
  const lines = [
    'Trade ID: ' + d.trade_id, 'Symbol: ' + fmt(d.symbol), 'Venue: ' + fmt(d.venue), 'Account: ' + fmt(d.account),
    'Execution timestamp: ' + fmt(d.execution_timestamp), 'Clearing timestamp: ' + fmt(d.clearing_timestamp), '',
    'Break Type: ' + d.break_type + (d.break_types.length > 1 ? ' (' + d.break_types.join(', ') + ')' : ''),
    'Severity: ' + d.severity, 'AI Confidence: ' + (d.ai_status === 'OK' ? d.ai_confidence : 'n/a (AI unavailable)'), '',
    'Execution Quantity: ' + fmt(d.quantity), 'Clearing Quantity: ' + fmt(d.clearing_quantity), 'Quantity Difference: ' + fmt(d.quantity_difference), '',
    'Execution Price: ' + fmt(d.price), 'Clearing Price: ' + fmt(d.clearing_price), 'Price Difference: ' + fmt(d.price_difference), '',
    'Trade Notional: ' + fmt(d.trade_notional) + ' ' + fmt(d.currency),
    'Clearing Delay (min): ' + fmt(d.clearing_delay_minutes) + ' [' + fmt(d.delay_basis) + ']', 'Clearing Status: ' + fmt(d.clearing_status), '',
    'Likely Root Cause: ' + causeLine, 'Recommended Action: ' + d.recommended_action, '',
    'Evidence:',
  ].concat(d.evidence.map((e) => '- ' + e)).concat(['', 'Automated Decision: ' + d.automated_decision, 'Workflow run: ' + d.workflow_run_id]);
  const description = lines.join(NL);
  const out = Object.assign({}, d, {
    material: material,
    dedup_key: dedupKey,
    jira_action: jiraAction,
    existing_issue_key: existingKey || '',
    jira_summary: '[TRADE BREAK][' + d.severity + '] ' + d.trade_id + ' - ' + d.break_type,
    jira_description: description,
    jira_priority_id: prio[d.severity],
    jira_comment: 'Automated update (run ' + d.workflow_run_id + ' at ' + d.processed_at + '): break still present.' + NL + NL + description,
    jira_issue_key: existingKey || '',
    jira_ticket_created: false, duplicate_prevented: false,
    manual_review: unconfirmed, workflow_error: d.ai_status === 'FAILED',
    error_detail: d.ai_error || '',
  });
  if (jiraAction === 'LOG_ONLY') {
    out.action_taken = capped ? 'JIRA_SKIPPED_TICKET_CAP_REACHED' : 'LOGGED_ONLY_BELOW_JIRA_THRESHOLD';
    out.processing_status = d.ai_status === 'FAILED' ? 'COMPLETED_WITH_AI_FALLBACK' : 'COMPLETED';
  } else if (jiraAction === 'IN_RUN_DUPLICATE') {
    out.action_taken = 'DUPLICATE_PREVENTED_IN_RUN';
    out.processing_status = d.ai_status === 'FAILED' ? 'COMPLETED_WITH_AI_FALLBACK' : 'COMPLETED';
    out.duplicate_prevented = true;
    out.error_detail = (d.ai_error || '');
  } else if (jiraAction === 'LOOKUP_FAILED') {
    out.action_taken = 'JIRA_DEDUP_LOOKUP_FAILED_RETRY_REQUIRED';
    out.processing_status = 'JIRA_FAILED_RETRY_REQUIRED';
    out.workflow_error = true;
    out.error_detail = ('Dedup lookups failed: registry=' + registryError + ' jira=' + lookupError + ' ' + (d.ai_error || '')).trim();
  }
  return { json: out };
});

// Operational metrics derived from the consolidated audit records of this run.
// Retry semantics: only failed external Jira actions are retryable. AI fallback and the ticket cap are not.
const rows = $('Consolidate Audit Records').all().map((i) => {
  const r = i.json;
  const retry = r.retry_required === true;
  return Object.assign({}, r, { retry_required: retry, retry_stage: retry ? (r.retry_stage || 'NONE') : 'NONE' });
});
const count = (f) => rows.filter(f).length;
const sev = (s) => count((r) => r.reconciliation_status === 'BREAK' && r.severity === s);
return [{ json: {
  workflow_run_id: String($execution.id),
  completed_at: new Date().toISOString(),
  total_trades_processed: rows.length,
  matched_trades: count((r) => r.reconciliation_status === 'MATCHED'),
  trade_breaks: count((r) => r.reconciliation_status === 'BREAK'),
  critical_breaks: sev('CRITICAL'),
  high_breaks: sev('HIGH'),
  medium_breaks: sev('MEDIUM'),
  low_breaks: sev('LOW'),
  jira_tickets_created: count((r) => r.jira_ticket_created === true),
  duplicate_tickets_prevented: count((r) => r.duplicate_prevented === true),
  manual_reviews_required: count((r) => r.manual_review === true),
  workflow_errors: count((r) => r.workflow_error === true),
  ai_fallbacks: count((r) => r.reconciliation_status === 'BREAK' && r.ai_status === 'FAILED'),
  jira_create_failures: count((r) => r.action_taken === 'JIRA_TICKET_CREATION_FAILED'),
  jira_comment_failures: count((r) => r.action_taken === 'DUPLICATE_PREVENTED_COMMENT_FAILED'),
  retry_required_count: count((r) => r.retry_required === true),
  failed_items_for_retry: rows.filter((r) => r.retry_required === true).map((r) => ({
    trade_id: r.trade_id, break_type: r.break_type, severity: r.severity, dedup_key: r.dedup_key,
    retry_stage: r.retry_stage, action_taken: r.action_taken, processing_status: r.processing_status, error_detail: r.error_detail,
  })),
} }];
